function validate([s, t]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 1 || s.length > 200000 || t.length < 1 || t.length > 200000) return 'Each string has 1 to 2 * 10^5 characters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 'Use only lowercase English letters.';
  return null;
}

