function minSteps(s, t) {
  const diff = new Array(26).fill(0);
  for (const ch of s) {
    diff[ch.charCodeAt(0) - 97]++;
  }
  for (const ch of t) {
    diff[ch.charCodeAt(0) - 97]--;
  }

  let steps = 0;
  for (const balance of diff) {
    steps += Math.abs(balance);
  }
  return steps;
}

