function minSteps(s, t) {
  const a = s.split('').sort(), b = t.split('').sort();
  let i = 0, j = 0, matched = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { matched++; i++; j++; }
    else if (a[i] < b[j]) i++;
    else j++;
  }
  return (a.length - matched) + (b.length - matched);
}

