function generate(rand, size) {
  const large = size === 'large';
  const letters = 1 + Math.floor(rand() * (large ? 26 : 5));
  const word = (length) => {
    let text = '';
    for (let i = 0; i < length; i++) text += String.fromCharCode(97 + Math.floor(rand() * letters));
    return text;
  };
  const maxLength = large ? 10000 : 8;
  const s = word(1 + Math.floor(rand() * maxLength));
  const mode = rand();
  if (mode < 0.2) {
    // A rearrangement of s, so the answer is 0.
    const chars = s.split('');
    for (let i = chars.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    return [s, chars.join('')];
  }
  if (mode < 0.4) {
    // s with a few characters dropped and a few added.
    let chars = s.split('').filter(() => rand() < 0.8);
    chars = chars.concat(word(Math.floor(rand() * (large ? 200 : 3))).split(''));
    if (!chars.length) chars = [word(1)];
    return [s, chars.join('')];
  }
  return [s, word(1 + Math.floor(rand() * maxLength))];
}
